    BUNDLE_VAR_notification_email: ${{ vars.NOTIFICATION_EMAIL }}
    BUNDLE_VAR_release: ${{ github.sha }}
  steps:
    - uses: actions/checkout@v4
    - uses: databricks/setup-cli@main
    - name: Validate
      run: databricks bundle validate --strict --target test
    - name: Deploy the same commit
      run: databricks bundle deploy --target test
    - name: Run in test
      run: databricks bundle run capability_guides_ingestion_framework --target test
    - name: Release summary
      run: |
        {
          echo "### Released ${GITHUB_SHA::7} to test"
          echo "- Bundle: capability-guides-ingestion"
          echo "- Resources tagged release=${GITHUB_SHA}"
        } >> "$GITHUB_STEP_SUMMARY"

